fn build_border_line(borders: &Borders, which: &str, col_widths: &[usize], padding: usize) -> Option<String> {
    // which = "top", "bottom", "mid"
    let (left, mid, right, h) = match which {
        "top" => (borders.top_left, borders.top_mid, borders.top_right, borders.top_h),
        "bottom" => (borders.bottom_left, borders.bottom_mid, borders.bottom_right, borders.bottom_h),
        "mid" => (borders.mid_left, borders.mid_mid, borders.mid_right, borders.mid_h),
        _ => (None, None, None, None),
    };
    if left.is_none() && mid.is_none() && right.is_none() && h.is_none() {
        return None;
    }
    // If no columns, border is left + right (if both exist)
    if col_widths.is_empty() {
        let mut s = String::new();
        if let Some(l) = left {
            s.push(l);
        }
        if let Some(r) = right {
            s.push(r);
        }
        // For Ascii2 and Markdown with no columns, mid case?
        // For 0 columns, we need to handle special: For Ascii2, top/bottom are None, so this won't be called.
        // For mid with 0 columns, what should it be?
        // For Ascii with 0 cols: top is "++" -> left '+' and right '+'.
        // So this logic works.
        return Some(s);
    }

    let mut s = String::new();
    if let Some(l) = left {
        s.push(l);
    }
    for (idx, &cw) in col_widths.iter().enumerate() {
        let total = cw + 2 * padding;
        let hc = h.unwrap_or(' ');
        for _ in 0..total {
            s.push(hc);
        }
        if idx + 1 < col_widths.len() {
            if let Some(m) = mid {
                s.push(m);
            }
        }
    }
    if let Some(r) = right {
        s.push(r);
    }
    Some(s)
}

fn build_row_line(
    borders: &Borders,
    col_widths: &[usize],
    cells: &[String], // already aligned strings (content aligned to col_width)
    cells_widths: &[usize], // display width of truncated content (for debugging)
    padding: usize,
) -> String {
    // cells are aligned strings that include spaces to fill col_width (their display width == col_width)
    // But we need to render as padding + aligned + padding with borders
    // Actually cells already include alignment spaces to fill col_width, but we still need padding
    // So final cell rendering: padding spaces + cell_aligned + padding spaces

    // For style None: no borders, just cells concatenated with padding

    let mut s = String::new();
    // left border
    if let Some(l) = borders.row_left {
        s.push(l);
    }
    for (idx, (cell_aligned, _)) in cells.iter().zip(cells_widths.iter()).enumerate() {
        // padding left
        for _ in 0..padding {
            s.push(' ');
        }
        s.push_str(cell_aligned);
        for _ in 0..padding {
            s.push(' ');
        }
        if idx + 1 < cells.len() {
            if let Some(m) = borders.row_mid {
                s.push(m);
            }
        }
    }
    if col_widths.is_empty() {
        // For 0 columns, row is just left+right? For ascii, left='|', right='|' => "||"
        // For none, left and right are None, so empty
        // For ascii2, left=' ', right=' ' => "  "
        // For markdown, left='|', right='|' => "||"
        // Our loop above with 0 cols does not produce anything, so we need to output left+right if both exist? Actually for 0 cols, we should output left+right combined?
        // Let's handle: if col_widths empty, row is left+right? But for None style, left and right None => empty string?
        // For ascii, left='|', right='|' => row should be "||"
        // For ascii2, left=' ', right=' ' => "  "
        // So for empty cols, we need to produce left+right if both Some, else just left/right? Let's see what ascii does: left='|' and right='|' => "||" yes.
        // For none, left None right None => "" (but earlier we had "\n" for empty? Actually none with 0 cols header row was empty line, not "||". Wait none with 0 cols should be empty line? In earlier test none empty default gave "\n" (empty line). That matches left None right None => "" -> empty line.
        // For markdown 0 cols: left='|' right='|' => "||" matches observed.
        // So for 0 cols, we should produce left+right if both exist, else what?
        // Let's produce: if left Some and right Some, combine. If only one, just that one? But for 0 cols, what about styles where left exists but right exists? We'll produce concatenated.
    }
    if let Some(r) = borders.row_right {
        s.push(r);
    }

    // Special handling for 0 columns: our loop didn't add anything, we only have left + right
    // So if col_widths empty, we have left + right (if we pushed left at start and right at end)
    // For example ascii: left='|' at start, right='|' at end => "||"
    // For none: left None right None => ""
    // For ascii2: left=' ' right=' ' => "  "
    // For markdown: left='|' right='|' => "||"
    // So our code already does left at start and right at end, so for 0 cols we will have left+right.

    s
}

fn main() {
    let cmd = Command::new("csview")
        .version("1.3.4")
        .about("A high performance csv viewer with cjk/emoji support.")
        .arg(Arg::new("FILE").help("File to view"))
        .arg(Arg::new("no-headers").short('H').long("no-headers").action(ArgAction::SetTrue).help("Specify that the input has no header row"))
        .arg(Arg::new("number").short('n').long("number").action(ArgAction::SetTrue).help("Prepend a column of line numbers to the table"))
        .arg(Arg::new("tsv").short('t').long("tsv").action(ArgAction::SetTrue).conflicts_with("delimiter").help("Use '\\t' as delimiter for tsv"))
        .arg(Arg::new("delimiter").short('d').long("delimiter").default_value(",").value_parser(value_parser!(char)).help("Specify the field delimiter [default: ,]"))
        .arg(Arg::new("style").short('s').long("style").default_value("sharp").value_parser(["none","ascii","ascii2","sharp","rounded","reinforced","markdown","grid"]).help("Specify the border style [possible values: none, ascii, ascii2, sharp, rounded, reinforced, markdown, grid]"))
        .arg(Arg::new("padding").short('p').long("padding").default_value("1").value_parser(value_parser!(usize)).help("Specify padding for table cell [default: 1]"))
        .arg(Arg::new("indent").short('i').long("indent").default_value("0").value_parser(value_parser!(usize)).help("Specify global indent for table [default: 0]"))
        .arg(Arg::new("sniff").long("sniff").default_value("1000").value_parser(value_parser!(usize)).help("Limit column widths sniffing to the specified number of rows. Specify \"0\" to cancel limit [default: 1000]"))
        .arg(Arg::new("header-align").long("header-align").default_value("center").value_parser(["left","center","right"]).help("Specify the alignment of the table header [possible values: left, center, right]"))
        .arg(Arg::new("body-align").long("body-align").default_value("left").value_parser(["left","center","right"]).help("Specify the alignment of the table body [possible values: left, center, right]"))
        .arg(Arg::new("disable-pager").short('P').long("disable-pager").action(ArgAction::SetTrue).help("Disable pager"))
        .get_matches();

    let file_opt: Option<String> = cmd.get_one::<String>("FILE").cloned();
    let no_headers = cmd.get_flag("no-headers");
    let number = cmd.get_flag("number");
    let tsv = cmd.get_flag("tsv");
    let delimiter: char = if tsv {
        '\t'
    } else {
        *cmd.get_one::<char>("delimiter").unwrap()
    };
    let style_str = cmd.get_one::<String>("style").unwrap().clone();
    let style = match style_str.as_str() {
        "none" => Style::None,
        "ascii" => Style::Ascii,
        "ascii2" => Style::Ascii2,
        "sharp" => Style::Sharp,
        "rounded" => Style::Rounded,
        "reinforced" => Style::Reinforced,
        "markdown" => Style::Markdown,
        "grid" => Style::Grid,
        _ => Style::Sharp,
    };
    let padding: usize = *cmd.get_one::<usize>("padding").unwrap();
    let indent: usize = *cmd.get_one::<usize>("indent").unwrap();
    let sniff_limit: usize = *cmd.get_one::<usize>("sniff").unwrap();
    let sniff = if sniff_limit == 0 { usize::MAX } else { sniff_limit };
    let header_align_str = cmd.get_one::<String>("header-align").unwrap().clone();
    let body_align_str = cmd.get_one::<String>("body-align").unwrap().clone();
    let header_align = match header_align_str.as_str() {
        "left" => Align::Left,
        "center" => Align::Center,
        "right" => Align::Right,
        _ => Align::Center,
    };
    let body_align = match body_align_str.as_str() {
        "left" => Align::Left,
        "center" => Align::Center,
        "right" => Align::Right,
        _ => Align::Left,
    };

    // Read input
    let input_string: String = if let Some(file_path) = file_opt {
        match std::fs::read_to_string(&file_path) {
            Ok(content) => content,
            Err(e) => {
                // For file not found, print exact message as original: csview: No such file or directory (os error 2)
                // Original prints that regardless of error? We'll try to match.
                // If e.kind is NotFound, print that message, else print generic?
                // For simplicity, if file not found, print that message.
                // The original's message uses "csview: No such file or directory (os error 2)"
                // Let's print same for any error to match observed.
                eprintln!("csview: No such file or directory (os error 2)");
                std::process::exit(1);
            }
        }
    } else {
        let mut buffer = String::new();
        let stdin = io::stdin();
        let mut handle = stdin.lock();
        match handle.read_to_string(&mut buffer) {
            Ok(_) => buffer,
            Err(_) => String::new(),
        }
    };

    // Parse CSV
    let parse_result = parse_csv(&input_string, delimiter);
    let (records, _infos) = match parse_result {
        Ok((rec, infos)) => (rec, infos),
        Err((rec_idx, line, byte, actual, expected)) => {
            eprintln!("csview: CSV error: record {} (line: {}, byte: {}): found record with {} fields, but the previous record has {} fields", rec_idx, line, byte, actual, expected);
            std::process::exit(1);
        }
    };

    // Now handle header and body
    let has_headers = !no_headers;

    let mut data_header: Option<Vec<String>> = None;
    let mut data_body: Vec<Vec<String>> = Vec::new();

    if has_headers {
        if records.is_empty() {
            data_header = Some(vec![]);
            data_body = vec![];
        } else {
            data_header = Some(records[0].clone());
            if records.len() > 1 {
                data_body = records[1..].to_vec();
            } else {
                data_body = vec![];
            }
        }
    } else {
        data_header = None;
        data_body = records.clone();
    }

    // Now handle number column
    let mut final_header: Option<Vec<String>> = None;
    let mut final_body: Vec<Vec<String>> = Vec::new();
    let mut num_columns: usize = 0;

    if number {
        // For header
        if has_headers {
            // header includes "#"
            let mut hdr = Vec::new();
            hdr.push("#".to_string());
            if let Some(ref dh) = data_header {
                hdr.extend(dh.clone());
            }
            final_header = Some(hdr);
            // body with numbers
            for (idx, row) in data_body.iter().enumerate() {
                let mut new_row = Vec::new();
                new_row.push((idx + 1).to_string());
                new_row.extend(row.clone());
                final_body.push(new_row);
            }
            num_columns = final_header.as_ref().map(|h| h.len()).unwrap_or(0);
            if num_columns == 0 {
                // When data_header is empty vec, header will be ["#"] => 1 col
                num_columns = 1;
            }
        } else {
            // no_headers
            final_header = None;
            for (idx, row) in data_body.iter().enumerate() {
                let mut new_row = Vec::new();
                new_row.push((idx + 1).to_string());
                new_row.extend(row.clone());
                final_body.push(new_row);
            }
            if data_body.is_empty() {
                // even with no data, we have 1 column for numbers (as observed)
                num_columns = 1;
            } else {
                num_columns = final_body.get(0).map(|r| r.len()).unwrap_or(1);
            }
        }
    } else {
        final_header = data_header.clone();
        final_body = data_body.clone();
        if let Some(ref hdr) = final_header {
            num_columns = hdr.len();
        } else if !final_body.is_empty() {
            num_columns = final_body[0].len();
        } else {
            num_columns = 0;
        }
    }

    // Edge: when has_headers true and records empty and number false, final_header is Some([]) with 0 cols, final_body empty, num_columns 0

    // Compute column widths
    let mut col_widths: Vec<usize> = vec![0; num_columns];

    // For number column width, always consider "#"
    if number {
        // col 0 is number column, include "#" width
        if !col_widths.is_empty() {
            let w = display_width("#");
            col_widths[0] = w;
        }
    }

    // If final_header is Some, include its widths (except for number column already considered? But for number case with has_headers, final_header includes "#", so we should include it anyway (it will be same)
    if let Some(ref hdr) = final_header {
        for (i, cell) in hdr.iter().enumerate() {
            if i < col_widths.len() {
                let w = display_width(cell);
                if w > col_widths[i] {
                    col_widths[i] = w;
                }
            }
        }
    }

    // For body, consider only first sniff rows
    let sniff_count = std::cmp::min(sniff, final_body.len());
    for row_idx in 0..sniff_count {
        let row = &final_body[row_idx];
        for (i, cell) in row.iter().enumerate() {
            if i < col_widths.len() {
                let w = display_width(cell);
                if w > col_widths[i] {
                    col_widths[i] = w;
                }
            }
        }
    }

    // For the case where number column has no header and no body (empty file with -n -H), col_widths is [0] but should be at least 1? Let's see our logic: we set col_widths[0] = width of "#" =1, so it will be 1. Good.

    // For data columns with empty file and has_headers false and number false, col_widths empty.

    // For data columns with has_headers true and records empty and number false, final_header Some([]) => num_columns 0, col_widths empty.

    // Now rendering

    let borders = get_borders(style);
    let indent_str = " ".repeat(indent);

    let mut output_lines: Vec<String> = Vec::new();

    // Helper to truncate cell to col_width if needed
    // For each cell, we need to truncate if its display width > col_width
    // Use truncate_str

    // Function to prepare cell aligned string and its width after truncation
    let prepare_cell = |cell: &String, col_width: usize, align: Align| -> (String, usize) {
        let cell_width = display_width(cell);
        let (truncated, trunc_width) = if cell_width > col_width {
            truncate_str(cell, col_width)
        } else {
            (cell.clone(), cell_width)
        };
        // Now align truncated to col_width
        let aligned = align_string(&truncated, trunc_width, col_width, align);
        (aligned, trunc_width)
    };

    // Determine if we have header row to show
    // final_header is Some if has_headers true (including empty case)
    // But for number && has_headers false, final_header None, no header row

    // For rendering, we need to consider cases:

    // If final_header is Some:
    //   Show top border (if style has top)
    //   Show header row
    //   If final_body not empty, show mid border (header separator)
    //   Show body rows (with body sep if grid)
    //   Show bottom border (if style has bottom)

    // If final_header is None:
    //   If final_body not empty:
    //     Show top border
    //     Show body rows (with body sep if grid)
    //     Show bottom border
    //   Else (final_body empty):
    //     If num_columns ==0:
