fn parse_csv(input: &str, delimiter: char) -> Result<(Vec<Vec<String>>, Vec<(usize, usize, usize)>), (usize, usize, usize, usize, usize)> {
    let mut records: Vec<Vec<String>> = Vec::new();
    let mut infos: Vec<(usize, usize, usize)> = Vec::new();

    let mut line: usize = 1;
    let mut record_start_byte: usize = 0;
    let mut record_start_line: usize = 1;
    let mut record_index: usize = 0;

    let mut field = String::new();
    let mut fields: Vec<String> = Vec::new();
    let mut in_quotes = false;
    let mut at_field_start = true;

    let mut expected_len: Option<usize> = None;

    let mut chars = input.char_indices().peekable();

    while let Some((byte_idx, ch)) = chars.next() {
        if ch == '\r' {
            let is_crlf = matches!(chars.peek(), Some((_, '\n')));
            if is_crlf {
                let (next_byte_idx, _) = chars.next().unwrap();
                if in_quotes {
                    field.push('\n');
                    line += 1;
                } else {
                    if at_field_start && fields.is_empty() && field.is_empty() {
                        record_start_byte = next_byte_idx + 1;
                        line += 1;
                        record_start_line = line;
                        field.clear();
                        fields.clear();
                        at_field_start = true;
                        continue;
                    }
                    fields.push(field.clone());
                    field.clear();
                    let actual = fields.len();
                    if let Some(exp) = expected_len {
                        if actual != exp {
                            return Err((record_index, record_start_line, record_start_byte, actual, exp));
                        }
                    } else {
                        expected_len = Some(actual);
                    }
                    records.push(fields.clone());
                    infos.push((record_start_byte, record_start_line, record_index));
                    fields.clear();
                    record_start_byte = next_byte_idx + 1;
                    line += 1;
                    record_start_line = line;
                    record_index += 1;
                    at_field_start = true;
                    in_quotes = false;
                }
                continue;
            } else {
                if in_quotes {
                    field.push('\n');
                    line += 1;
                } else {
                    if at_field_start && fields.is_empty() && field.is_empty() {
                        record_start_byte = byte_idx + ch.len_utf8();
                        line += 1;
                        record_start_line = line;
                        field.clear();
                        fields.clear();
                        at_field_start = true;
                        continue;
                    }
                    fields.push(field.clone());
                    field.clear();
                    let actual = fields.len();
                    if let Some(exp) = expected_len {
                        if actual != exp {
                            return Err((record_index, record_start_line, record_start_byte, actual, exp));
                        }
                    } else {
                        expected_len = Some(actual);
                    }
                    records.push(fields.clone());
                    infos.push((record_start_byte, record_start_line, record_index));
                    fields.clear();
                    record_start_byte = byte_idx + ch.len_utf8();
                    line += 1;
                    record_start_line = line;
                    record_index += 1;
                    at_field_start = true;
                    in_quotes = false;
                }
                continue;
            }
        }

        if ch == '\n' {
            if in_quotes {
                field.push('\n');
                line += 1;
            } else {
                if at_field_start && fields.is_empty() && field.is_empty() {
                    record_start_byte = byte_idx + ch.len_utf8();
                    line += 1;
                    record_start_line = line;
                    field.clear();
                    fields.clear();
                    at_field_start = true;
                    continue;
                }
                fields.push(field.clone());
                field.clear();
                let actual = fields.len();
                if let Some(exp) = expected_len {
                    if actual != exp {
                        return Err((record_index, record_start_line, record_start_byte, actual, exp));
                    }
                } else {
                    expected_len = Some(actual);
                }
                records.push(fields.clone());
                infos.push((record_start_byte, record_start_line, record_index));
                fields.clear();
                record_start_byte = byte_idx + ch.len_utf8();
                line += 1;
                record_start_line = line;
                record_index += 1;
                at_field_start = true;
                in_quotes = false;
            }
            continue;
        }

        if ch == delimiter && !in_quotes {
            fields.push(field.clone());
            field.clear();
            at_field_start = true;
            continue;
        }

        if ch == '"' {
            if at_field_start && !in_quotes {
                in_quotes = true;
                at_field_start = false;
                continue;
            } else if in_quotes {
                if let Some((_, '"')) = chars.peek() {
                    field.push('"');
                    chars.next();
                    at_field_start = false;
                } else {
                    in_quotes = false;
                    at_field_start = false;
                }
                continue;
            } else {
                field.push(ch);
                at_field_start = false;
                continue;
            }
        }

        field.push(ch);
        at_field_start = false;
    }

    if !fields.is_empty() || !field.is_empty() || !at_field_start {
        fields.push(field.clone());
        let actual = fields.len();
        if let Some(exp) = expected_len {
            if actual != exp {
                return Err((record_index, record_start_line, record_start_byte, actual, exp));
            }
        }
        records.push(fields.clone());
        infos.push((record_start_byte, record_start_line, record_index));
    }

    Ok((records, infos))
}

fn display_width(s: &str) -> usize {
    UnicodeWidthStr::width(s)
}

fn truncate_str(s: &str, max_width: usize) -> (String, usize) {
    let (truncated, width) = s.unicode_truncate(max_width);
    (truncated.to_string(), width)
}

fn align_string(content: &str, content_width: usize, col_width: usize, align: Align) -> String {
    let remaining = col_width.saturating_sub(content_width);
    match align {
        Align::Left => {
            let mut res = String::new();
            res.push_str(content);
            for _ in 0..remaining {
                res.push(' ');
            }
            res
        }
        Align::Right => {
            let mut res = String::new();
            for _ in 0..remaining {
                res.push(' ');
            }
            res.push_str(content);
            res
        }
        Align::Center => {
            let left = remaining / 2;
            let right = remaining - left;
            let mut res = String::new();
            for _ in 0..left {
                res.push(' ');
            }
            res.push_str(content);
            for _ in 0..right {
                res.push(' ');
            }
            res
        }
    }
}

