    _col_widths: &[usize],
    cells: &[String],
    _cells_widths: &[usize],
    padding: usize,
) -> String {
    let mut s = String::new();
    if let Some(l) = borders.row_left {
        s.push(l);
    }
    for (idx, cell_aligned) in cells.iter().enumerate() {
        for _ in 0..padding {
            s.push(' ');
        }
        s.push_str(cell_aligned);
        for _ in 0..padding {
            s.push(' ');
        }
        if idx + 1 < cells.len() {
