    }
    let mut s = String::new();
    if let Some(l) = left {
        s.push(l);
    }
    for (idx, &cw) in col_widths.iter().enumerate() {
        let total = cw + 2 * padding;
        let hc = h.unwrap_or(' ');
        for _ in 0..total {
            s.push(hc);
        }
        if idx + 1 < col_widths.len() {
            if let Some(m) = mid {
                s.push(m);
            }
        }
    }
    if let Some(r) = right {
        s.push(r);
    }
    Some(s)
}

fn build_row_line(
    borders: &Borders,
    _col_widths: &[usize],
    cells: &[String],
    _cells_widths: &[usize],
    padding: usize,
) -> String {
    let mut s = String::new();
    if let Some(l) = borders.row_left {
        s.push(l);
    }
    for (idx, cell_aligned) in cells.iter().enumerate() {
        for _ in 0..padding {
            s.push(' ');
        }
        s.push_str(cell_aligned);
        for _ in 0..padding {
            s.push(' ');
        }
        if idx + 1 < cells.len() {
            if let Some(m) = borders.row_mid {
                s.push(m);
            }
        }
    }
    if let Some(r) = borders.row_right {
        s.push(r);
    }
    s
}

