use clap::{Arg, ArgAction, Command, value_parser};
use std::io::{self, Read};
use unicode_width::UnicodeWidthStr;
use unicode_truncate::UnicodeTruncateStr;

#[derive(Copy, Clone, Debug, PartialEq)]
enum Style {
    None,
    Ascii,
    Ascii2,
    Sharp,
    Rounded,
    Reinforced,
    Markdown,
    Grid,
}

#[derive(Copy, Clone, Debug, PartialEq)]
enum Align {
