}

fn display_width(s: &str) -> usize {
    UnicodeWidthStr::width(s)
}

fn truncate_str(s: &str, max_width: usize) -> (String, usize) {
    let (truncated, width) = s.unicode_truncate(max_width);
    (truncated.to_string(), width)
}

fn align_string(content: &str, content_width: usize, col_width: usize, align: Align) -> String {
    let remaining = col_width.saturating_sub(content_width);
    match align {
        Align::Left => {
            let mut res = String::new();
            res.push_str(content);
            for _ in 0..remaining {
                res.push(' ');
            }
            res
        }
        Align::Right => {
            let mut res = String::new();
            for _ in 0..remaining {
                res.push(' ');
            }
            res.push_str(content);
            res
        }
        Align::Center => {
            let left = remaining / 2;
            let right = remaining - left;
            let mut res = String::new();
            for _ in 0..left {
                res.push(' ');
            }
            res.push_str(content);
            for _ in 0..right {
                res.push(' ');
            }
            res
        }
    }
}

struct Borders {
    top_left: Option<char>,
    top_mid: Option<char>,
    top_right: Option<char>,
    top_h: Option<char>,
    bottom_left: Option<char>,
    bottom_mid: Option<char>,
    bottom_right: Option<char>,
    bottom_h: Option<char>,
    mid_left: Option<char>,
    mid_mid: Option<char>,
    mid_right: Option<char>,
    mid_h: Option<char>,
    row_left: Option<char>,
    row_mid: Option<char>,
    row_right: Option<char>,
}

fn get_borders(style: Style) -> Borders {
    match style {
        Style::Sharp => Borders {
            top_left: Some('┌'),
            top_mid: Some('┬'),
            top_right: Some('┐'),
            top_h: Some('─'),
            bottom_left: Some('└'),
            bottom_mid: Some('┴'),
            bottom_right: Some('┘'),
            bottom_h: Some('─'),
            mid_left: Some('├'),
            mid_mid: Some('┼'),
            mid_right: Some('┤'),
            mid_h: Some('─'),
            row_left: Some('│'),
