fn build_border_line(borders: &Borders, which: &str, col_widths: &[usize], padding: usize) -> Option<String> {
    let (left, mid, right, h) = match which {
        "top" => (borders.top_left, borders.top_mid, borders.top_right, borders.top_h),
        "bottom" => (borders.bottom_left, borders.bottom_mid, borders.bottom_right, borders.bottom_h),
        "mid" => (borders.mid_left, borders.mid_mid, borders.mid_right, borders.mid_h),
        _ => (None, None, None, None),
    };
    if left.is_none() && mid.is_none() && right.is_none() && h.is_none() {
        return None;
    }
    if col_widths.is_empty() {
        let mut s = String::new();
        if let Some(l) = left {
            s.push(l);
        }
        if let Some(r) = right {
            s.push(r);
        }
        return Some(s);
    }
    let mut s = String::new();
    if let Some(l) = left {
        s.push(l);
    }
    for (idx, &cw) in col_widths.iter().enumerate() {
        let total = cw + 2 * padding;
        let hc = h.unwrap_or(' ');
        for _ in 0..total {
            s.push(hc);
        }
        if idx + 1 < col_widths.len() {
            if let Some(m) = mid {
                s.push(m);
            }
        }
    }
    if let Some(r) = right {
        s.push(r);
    }
    Some(s)
}

fn build_row_line(
    borders: &Borders,
    _col_widths: &[usize],
    cells: &[String],
    _cells_widths: &[usize],
    padding: usize,
) -> String {
    let mut s = String::new();
    if let Some(l) = borders.row_left {
        s.push(l);
    }
    for (idx, cell_aligned) in cells.iter().enumerate() {
        for _ in 0..padding {
            s.push(' ');
        }
        s.push_str(cell_aligned);
        for _ in 0..padding {
            s.push(' ');
        }
        if idx + 1 < cells.len() {
            if let Some(m) = borders.row_mid {
                s.push(m);
            }
        }
    }
    if let Some(r) = borders.row_right {
        s.push(r);
    }
    s
}

fn main() {
    let cmd = Command::new("csview")
        .version("1.3.4")
        .about("A high performance csv viewer with cjk/emoji support.")
        .next_line_help(true)
        .arg(Arg::new("FILE").help("File to view"))
        .arg(Arg::new("no-headers").short('H').long("no-headers").action(ArgAction::SetTrue).help("Specify that the input has no header row"))
        .arg(Arg::new("number").short('n').long("number").action(ArgAction::SetTrue).help("Prepend a column of line numbers to the table"))
        .arg(Arg::new("tsv").short('t').long("tsv").action(ArgAction::SetTrue).conflicts_with("delimiter").help("Use '\\t' as delimiter for tsv"))
        .arg(Arg::new("delimiter").short('d').long("delimiter").default_value(",").value_name("DELIMITER").value_parser(value_parser!(char)).help("Specify the field delimiter"))
        .arg(Arg::new("style").short('s').long("style").default_value("sharp").value_name("STYLE").value_parser(["none","ascii","ascii2","sharp","rounded","reinforced","markdown","grid"]).help("Specify the border style"))
        .arg(Arg::new("padding").short('p').long("padding").default_value("1").value_name("PADDING").value_parser(value_parser!(usize)).help("Specify padding for table cell"))
        .arg(Arg::new("indent").short('i').long("indent").default_value("0").value_name("INDENT").value_parser(value_parser!(usize)).help("Specify global indent for table"))
        .arg(Arg::new("sniff").long("sniff").default_value("1000").value_name("LIMIT").value_parser(value_parser!(usize)).help("Limit column widths sniffing to the specified number of rows. Specify \"0\" to cancel limit"))
        .arg(Arg::new("header-align").long("header-align").default_value("center").value_name("HEADER_ALIGN").value_parser(["left","center","right"]).help("Specify the alignment of the table header"))
        .arg(Arg::new("body-align").long("body-align").default_value("left").value_name("BODY_ALIGN").value_parser(["left","center","right"]).help("Specify the alignment of the table body"))
        .arg(Arg::new("disable-pager").short('P').long("disable-pager").action(ArgAction::SetTrue).help("Disable pager"))
        .get_matches();

    let file_opt: Option<String> = cmd.get_one::<String>("FILE").cloned();
    let no_headers = cmd.get_flag("no-headers");
    let number = cmd.get_flag("number");
    let tsv = cmd.get_flag("tsv");
    let delimiter: char = if tsv { '\t' } else { *cmd.get_one::<char>("delimiter").unwrap() };
    let style_str = cmd.get_one::<String>("style").unwrap().clone();
    let style = match style_str.as_str() {
        "none" => Style::None,
        "ascii" => Style::Ascii,
        "ascii2" => Style::Ascii2,
        "sharp" => Style::Sharp,
        "rounded" => Style::Rounded,
        "reinforced" => Style::Reinforced,
        "markdown" => Style::Markdown,
        "grid" => Style::Grid,
        _ => Style::Sharp,
    };
    let padding: usize = *cmd.get_one::<usize>("padding").unwrap();
    let indent: usize = *cmd.get_one::<usize>("indent").unwrap();
    let sniff_limit: usize = *cmd.get_one::<usize>("sniff").unwrap();
    let sniff = if sniff_limit == 0 { usize::MAX } else { sniff_limit };
    let header_align_str = cmd.get_one::<String>("header-align").unwrap().clone();
    let body_align_str = cmd.get_one::<String>("body-align").unwrap().clone();
    let header_align = match header_align_str.as_str() {
        "left" => Align::Left,
        "center" => Align::Center,
        "right" => Align::Right,
        _ => Align::Center,
    };
    let body_align = match body_align_str.as_str() {
        "left" => Align::Left,
        "center" => Align::Center,
        "right" => Align::Right,
        _ => Align::Left,
    };

    let input_string: String = if let Some(file_path) = file_opt {
        match std::fs::read_to_string(&file_path) {
            Ok(content) => content,
            Err(_) => {
                eprintln!("csview: No such file or directory (os error 2)");
                std::process::exit(1);
            }
        }
    } else {
        let mut buffer = String::new();
        let stdin = io::stdin();
        let mut handle = stdin.lock();
        match handle.read_to_string(&mut buffer) {
            Ok(_) => buffer,
            Err(_) => String::new(),
        }
    };

    let parse_result = parse_csv(&input_string, delimiter);
    let (records, _infos) = match parse_result {
        Ok((rec, infos)) => (rec, infos),
        Err((rec_idx, line, byte, actual, expected)) => {
            eprintln!("csview: CSV error: record {} (line: {}, byte: {}): found record with {} fields, but the previous record has {} fields", rec_idx, line, byte, actual, expected);
            std::process::exit(1);
        }
    };

    let has_headers = !no_headers;

    let mut data_header: Option<Vec<String>> = None;
    let mut data_body: Vec<Vec<String>> = Vec::new();

    if has_headers {
        if records.is_empty() {
            data_header = Some(vec![]);
            data_body = vec![];
        } else {
            data_header = Some(records[0].clone());
            if records.len() > 1 {
                data_body = records[1..].to_vec();
            } else {
                data_body = vec![];
            }
        }
    } else {
        data_header = None;
        data_body = records.clone();
    }

    let mut final_header: Option<Vec<String>> = None;
    let mut final_body: Vec<Vec<String>> = Vec::new();
    let mut num_columns: usize = 0;

    if number {
        if has_headers {
            let mut hdr = Vec::new();
            hdr.push("#".to_string());
            if let Some(ref dh) = data_header {
                hdr.extend(dh.clone());
            }
            final_header = Some(hdr);
            for (idx, row) in data_body.iter().enumerate() {
                let mut new_row = Vec::new();
                new_row.push((idx + 1).to_string());
                new_row.extend(row.clone());
                final_body.push(new_row);
            }
            num_columns = final_header.as_ref().map(|h| h.len()).unwrap_or(0);
            if num_columns == 0 {
                num_columns = 1;
            }
        } else {
            final_header = None;
            for (idx, row) in data_body.iter().enumerate() {
                let mut new_row = Vec::new();
                new_row.push((idx + 1).to_string());
                new_row.extend(row.clone());
                final_body.push(new_row);
            }
            if data_body.is_empty() {
                num_columns = 1;
            } else {
                num_columns = final_body.get(0).map(|r| r.len()).unwrap_or(1);
            }
        }
    } else {
        final_header = data_header.clone();
        final_body = data_body.clone();
        if let Some(ref hdr) = final_header {
            num_columns = hdr.len();
        } else if !final_body.is_empty() {
            num_columns = final_body[0].len();
        } else {
            num_columns = 0;
        }
    }

    let mut col_widths: Vec<usize> = vec![0; num_columns];

    if number && !col_widths.is_empty() {
        let w = display_width("#");
        col_widths[0] = w;
    }

    if let Some(ref hdr) = final_header {
        for (i, cell) in hdr.iter().enumerate() {
            if i < col_widths.len() {
                let w = display_width(cell);
                if w > col_widths[i] {
                    col_widths[i] = w;
                }
            }
        }
    }

    let sniff_count = std::cmp::min(sniff, final_body.len());
    for row_idx in 0..sniff_count {
        let row = &final_body[row_idx];
        for (i, cell) in row.iter().enumerate() {
            if i < col_widths.len() {
                let w = display_width(cell);
                if w > col_widths[i] {
                    col_widths[i] = w;
                }
            }
        }
    }

    let borders = get_borders(style);
    let indent_str = " ".repeat(indent);

    let mut output_lines: Vec<String> = Vec::new();

    if let Some(hdr) = final_header {
        if let Some(top) = build_border_line(&borders, "top", &col_widths, padding) {
            output_lines.push(format!("{}{}", indent_str, top));
        }
        let mut aligned_cells = Vec::new();
        let mut cell_widths = Vec::new();
        for (i, cell) in hdr.iter().enumerate() {
            let cw = col_widths.get(i).cloned().unwrap_or(0);
            let cell_width = display_width(cell);
            let (truncated, trunc_width) = if cell_width > cw {
                truncate_str(cell, cw)
            } else {
                (cell.clone(), cell_width)
            };
            let aligned = align_string(&truncated, trunc_width, cw, header_align);
            aligned_cells.push(aligned);
            cell_widths.push(trunc_width);
        }
        let row_line = build_row_line(&borders, &col_widths, &aligned_cells, &cell_widths, padding);
        output_lines.push(format!("{}{}", indent_str, row_line));

        if !final_body.is_empty() {
            if let Some(mid) = build_border_line(&borders, "mid", &col_widths, padding) {
                output_lines.push(format!("{}{}", indent_str, mid));
            }
            for (body_idx, row) in final_body.iter().enumerate() {
                let mut aligned_cells = Vec::new();
                let mut cell_widths = Vec::new();
                for (i, cell) in row.iter().enumerate() {
                    let cw = col_widths.get(i).cloned().unwrap_or(0);
                    let cell_width = display_width(cell);
                    let (truncated, trunc_width) = if cell_width > cw {
                        truncate_str(cell, cw)
                    } else {
                        (cell.clone(), cell_width)
                    };
                    let aligned = align_string(&truncated, trunc_width, cw, body_align);
                    aligned_cells.push(aligned);
                    cell_widths.push(trunc_width);
                }
                let row_line = build_row_line(&borders, &col_widths, &aligned_cells, &cell_widths, padding);
                output_lines.push(format!("{}{}", indent_str, row_line));
                if style == Style::Grid && body_idx + 1 < final_body.len() {
                    if let Some(mid) = build_border_line(&borders, "mid", &col_widths, padding) {
                        output_lines.push(format!("{}{}", indent_str, mid));
                    }
                }
            }
        }

        if let Some(bottom) = build_border_line(&borders, "bottom", &col_widths, padding) {
            output_lines.push(format!("{}{}", indent_str, bottom));
        }
    } else {
        if final_body.is_empty() {
            if let Some(top) = build_border_line(&borders, "top", &col_widths, padding) {
                output_lines.push(format!("{}{}", indent_str, top));
            }
            if let Some(bottom) = build_border_line(&borders, "bottom", &col_widths, padding) {
                output_lines.push(format!("{}{}", indent_str, bottom));
            }
        } else {
            if let Some(top) = build_border_line(&borders, "top", &col_widths, padding) {
                output_lines.push(format!("{}{}", indent_str, top));
            }
            for (body_idx, row) in final_body.iter().enumerate() {
                let mut aligned_cells = Vec::new();
                let mut cell_widths = Vec::new();
                for (i, cell) in row.iter().enumerate() {
                    let cw = col_widths.get(i).cloned().unwrap_or(0);
                    let cell_width = display_width(cell);
                    let (truncated, trunc_width) = if cell_width > cw {
                        truncate_str(cell, cw)
                    } else {
                        (cell.clone(), cell_width)
                    };
                    let aligned = align_string(&truncated, trunc_width, cw, body_align);
                    aligned_cells.push(aligned);
                    cell_widths.push(trunc_width);
                }
                let row_line = build_row_line(&borders, &col_widths, &aligned_cells, &cell_widths, padding);
                output_lines.push(format!("{}{}", indent_str, row_line));
                if style == Style::Grid && body_idx + 1 < final_body.len() {
                    if let Some(mid) = build_border_line(&borders, "mid", &col_widths, padding) {
                        output_lines.push(format!("{}{}", indent_str, mid));
                    }
                }
            }
            if let Some(bottom) = build_border_line(&borders, "bottom", &col_widths, padding) {
                output_lines.push(format!("{}{}", indent_str, bottom));
            }
        }
    }

    for line in output_lines {
        println!("{}", line);
    }
}
