                record_index += 1;
                at_field_start = true;
                in_quotes = false;
            }
            continue;
        }
        if ch == delimiter && !in_quotes {
            fields.push(field.clone());
            field.clear();
            at_field_start = true;
            continue;
        }
        if ch == '"' {
            if at_field_start && !in_quotes {
                in_quotes = true;
                at_field_start = false;
                continue;
            } else if in_quotes {
                if let Some((_, '"')) = chars.peek() {
                    field.push('"');
                    chars.next();
                    at_field_start = false;
                } else {
                    in_quotes = false;
                    at_field_start = false;
                }
                continue;
            } else {
