use clap::{Arg, ArgAction, Command, value_parser};
use std::io::{self, Read};
use unicode_width::UnicodeWidthStr;
use unicode_truncate::UnicodeTruncateStr;

#[derive(Copy, Clone, Debug, PartialEq)]
enum Style { None, Ascii, Ascii2, Sharp, Rounded, Reinforced, Markdown, Grid, }
#[derive(Copy, Clone, Debug, PartialEq)]
enum Align { Left, Center, Right, }

fn parse_csv(input: &str, delimiter: char) -> Result<Vec<Vec<String>>, (usize, usize, usize, usize, usize)> {
    let mut records: Vec<Vec<String>> = Vec::new();
    let mut line: usize = 1;
    let mut record_start_byte: usize = 0;
    let mut record_start_line: usize = 1;
    let mut record_index: usize = 0;
