                    record_index += 1;
                    at_field_start = true;
                    in_quotes = false;
                }
                continue;
            }
        }
        if ch == '\n' {
            if in_quotes {
                field.push('\n');
                line += 1;
            } else {
                if at_field_start && fields.is_empty() && field.is_empty() {
                    record_start_byte = byte_idx + ch.len_utf8();
                    line += 1;
