                    fields.clear();
                    record_start_byte = next_byte_idx + 1;
                    line += 1;
                    record_start_line = line;
                    record_index += 1;
                    at_field_start = true;
                    in_quotes = false;
                }
                continue;
            } else {
                if in_quotes {
                    field.push('\n');
                    line += 1;
                } else {
                    if at_field_start && fields.is_empty() && field.is_empty() {
                        record_start_byte = byte_idx + ch.len_utf8();
                        line += 1;
                        record_start_line = line;
                        field.clear();
                        fields.clear();
                        at_field_start = true;
                        continue;
                    }
                    fields.push(field.clone());
                    field.clear();
                    let actual = fields.len();
                    if let Some(exp) = expected_len {
                        if actual != exp {
                            return Err((record_index, record_start_line, record_start_byte, actual, exp));
                        }
                    } else { expected_len = Some(actual); }
                    records.push(fields.clone());
                    fields.clear();
                    record_start_byte = byte_idx + ch.len_utf8();
                    line += 1;
                    record_start_line = line;
                    record_index += 1;
                    at_field_start = true;
                    in_quotes = false;
                }
                continue;
            }
        }
        if ch == '\n' {
            if in_quotes {
                field.push('\n');
                line += 1;
            } else {
                if at_field_start && fields.is_empty() && field.is_empty() {
                    record_start_byte = byte_idx + ch.len_utf8();
                    line += 1;
                    record_start_line = line;
                    field.clear();
                    fields.clear();
                    at_field_start = true;
                    continue;
                }
                fields.push(field.clone());
                field.clear();
                let actual = fields.len();
                if let Some(exp) = expected_len {
                    if actual != exp {
                        return Err((record_index, record_start_line, record_start_byte, actual, exp));
                    }
                } else { expected_len = Some(actual); }
                records.push(fields.clone());
                fields.clear();
                record_start_byte = byte_idx + ch.len_utf8();
                line += 1;
                record_start_line = line;
                record_index += 1;
                at_field_start = true;
                in_quotes = false;
            }
            continue;
        }
        if ch == delimiter && !in_quotes {
            fields.push(field.clone());
            field.clear();
            at_field_start = true;
            continue;
        }
        if ch == '"' {
            if at_field_start && !in_quotes {
                in_quotes = true;
                at_field_start = false;
                continue;
            } else if in_quotes {
                if let Some((_, '"')) = chars.peek() {
                    field.push('"');
                    chars.next();
                    at_field_start = false;
                } else {
                    in_quotes = false;
                    at_field_start = false;
                }
                continue;
            } else {
                field.push(ch);
                at_field_start = false;
                continue;
            }
        }
        field.push(ch);
        at_field_start = false;
    }
    if !fields.is_empty() || !field.is_empty() || !at_field_start {
        fields.push(field.clone());
        let actual = fields.len();
        if let Some(exp) = expected_len {
            if actual != exp {
                return Err((record_index, record_start_line, record_start_byte, actual, exp));
            }
        }
        records.push(fields.clone());
    }
    Ok(records)
}

fn display_width(s: &str) -> usize { UnicodeWidthStr::width(s) }
fn truncate_str(s: &str, max_width: usize) -> (String, usize) {
    let (t,w) = s.unicode_truncate(max_width);
    (t.to_string(), w)
}
fn align_string(content: &str, content_width: usize, col_width: usize, align: Align) -> String {
    let remaining = col_width.saturating_sub(content_width);
    match align {
        Align::Left => { let mut r=String::new(); r.push_str(content); for _ in 0..remaining { r.push(' '); } r },
        Align::Right => { let mut r=String::new(); for _ in 0..remaining { r.push(' '); } r.push_str(content); r },
        Align::Center => { let left=remaining/2; let right=remaining-left; let mut r=String::new(); for _ in 0..left { r.push(' '); } r.push_str(content); for _ in 0..right { r.push(' '); } r },
    }
}

struct Borders {
    top_left: Option<char>, top_mid: Option<char>, top_right: Option<char>, top_h: Option<char>,
    bottom_left: Option<char>, bottom_mid: Option<char>, bottom_right: Option<char>, bottom_h: Option<char>,
    mid_left: Option<char>, mid_mid: Option<char>, mid_right: Option<char>, mid_h: Option<char>,
    row_left: Option<char>, row_mid: Option<char>, row_right: Option<char>,
}
fn get_borders(style: Style) -> Borders {
    match style {
        Style::Sharp => Borders { top_left: Some('┌'), top_mid: Some('┬'), top_right: Some('┐'), top_h: Some('─'), bottom_left: Some('└'), bottom_mid: Some('┴'), bottom_right: Some('┘'), bottom_h: Some('─'), mid_left: Some('├'), mid_mid: Some('┼'), mid_right: Some('┤'), mid_h: Some('─'), row_left: Some('│'), row_mid: Some('│'), row_right: Some('│'), },
        Style::Rounded => Borders { top_left: Some('╭'), top_mid: Some('┬'), top_right: Some('╮'), top_h: Some('─'), bottom_left: Some('╰'), bottom_mid: Some('┴'), bottom_right: Some('╯'), bottom_h: Some('─'), mid_left: Some('├'), mid_mid: Some('┼'), mid_right: Some('┤'), mid_h: Some('─'), row_left: Some('│'), row_mid: Some('│'), row_right: Some('│'), },
        Style::Reinforced => Borders { top_left: Some('┏'), top_mid: Some('┬'), top_right: Some('┓'), top_h: Some('─'), bottom_left: Some('┗'), bottom_mid: Some('┴'), bottom_right: Some('┛'), bottom_h: Some('─'), mid_left: Some('├'), mid_mid: Some('┼'), mid_right: Some('┤'), mid_h: Some('─'), row_left: Some('│'), row_mid: Some('│'), row_right: Some('│'), },
        Style::Ascii => Borders { top_left: Some('+'), top_mid: Some('+'), top_right: Some('+'), top_h: Some('-'), bottom_left: Some('+'), bottom_mid: Some('+'), bottom_right: Some('+'), bottom_h: Some('-'), mid_left: Some('+'), mid_mid: Some('+'), mid_right: Some('+'), mid_h: Some('-'), row_left: Some('|'), row_mid: Some('|'), row_right: Some('|'), },
        Style::Ascii2 => Borders { top_left: None, top_mid: None, top_right: None, top_h: None, bottom_left: None, bottom_mid: None, bottom_right: None, bottom_h: None, mid_left: Some(' '), mid_mid: Some('+'), mid_right: Some(' '), mid_h: Some('-'), row_left: Some(' '), row_mid: Some('|'), row_right: Some(' '), },
        Style::Markdown => Borders { top_left: None, top_mid: None, top_right: None, top_h: None, bottom_left: None, bottom_mid: None, bottom_right: None, bottom_h: None, mid_left: Some('|'), mid_mid: Some('|'), mid_right: Some('|'), mid_h: Some('-'), row_left: Some('|'), row_mid: Some('|'), row_right: Some('|'), },
        Style::Grid => Borders { top_left: Some('┌'), top_mid: Some('┬'), top_right: Some('┐'), top_h: Some('─'), bottom_left: Some('└'), bottom_mid: Some('┴'), bottom_right: Some('┘'), bottom_h: Some('─'), mid_left: Some('├'), mid_mid: Some('┼'), mid_right: Some('┤'), mid_h: Some('─'), row_left: Some('│'), row_mid: Some('│'), row_right: Some('│'), },
        Style::None => Borders { top_left: None, top_mid: None, top_right: None, top_h: None, bottom_left: None, bottom_mid: None, bottom_right: None, bottom_h: None, mid_left: None, mid_mid: None, mid_right: None, mid_h: None, row_left: None, row_mid: None, row_right: None, },
    }
}
fn build_border_line(borders: &Borders, which: &str, col_widths: &[usize], padding: usize) -> Option<String> {
    let (left, mid, right, h) = match which {
        "top" => (borders.top_left, borders.top_mid, borders.top_right, borders.top_h),
        "bottom" => (borders.bottom_left, borders.bottom_mid, borders.bottom_right, borders.bottom_h),
        "mid" => (borders.mid_left, borders.mid_mid, borders.mid_right, borders.mid_h),
        _ => (None, None, None, None),
    };
    if left.is_none() && mid.is_none() && right.is_none() && h.is_none() { return None; }
    if col_widths.is_empty() {
        let mut s = String::new();
        if let Some(l) = left { s.push(l); }
        if let Some(r) = right { s.push(r); }
        return Some(s);
    }
    let mut s = String::new();
    if let Some(l) = left { s.push(l); }
    for (idx, &cw) in col_widths.iter().enumerate() {
        let total = cw + 2 * padding;
        let hc = h.unwrap_or(' ');
        for _ in 0..total { s.push(hc); }
        if idx + 1 < col_widths.len() {
            if let Some(m) = mid { s.push(m); }
        }
    }
    if let Some(r) = right { s.push(r); }
    Some(s)
}
fn build_row_line(borders: &Borders, cells: &[String], padding: usize) -> String {
    let mut s = String::new();
    if let Some(l) = borders.row_left { s.push(l); }
    for (idx, cell_aligned) in cells.iter().enumerate() {
        for _ in 0..padding { s.push(' '); }
        s.push_str(cell_aligned);
        for _ in 0..padding { s.push(' '); }
        if idx + 1 < cells.len() {
            if let Some(m) = borders.row_mid { s.push(m); }
        }
    }
    if let Some(r) = borders.row_right { s.push(r); }
    s
}

fn main() {
    let term_width = std::env::var("COLUMNS").ok().and_then(|s| s.parse::<usize>().ok()).unwrap_or(100);
    eprintln!("DEBUG term_width={}", term_width);
    let cmd = Command::new("executable")
        .version("1.3.4")
        .about("A high performance csv viewer with cjk/emoji support.")
        .next_line_help(true)
        .term_width(term_width)
        .max_term_width(term_width)
        .arg(Arg::new("FILE").help("File to view"))
        .arg(Arg::new("no-headers").short('H').long("no-headers").action(ArgAction::SetTrue).help("Specify that the input has no header row"))
        .arg(Arg::new("number").short('n').long("number").action(ArgAction::SetTrue).help("Prepend a column of line numbers to the table"))
        .arg(Arg::new("tsv").short('t').long("tsv").action(ArgAction::SetTrue).conflicts_with("delimiter").help("Use '\\t' as delimiter for tsv"))
        .arg(Arg::new("delimiter").short('d').long("delimiter").default_value(",").value_name("DELIMITER").value_parser(value_parser!(char)).help("Specify the field delimiter"))
        .arg(Arg::new("style").short('s').long("style").default_value("sharp").value_name("STYLE").value_parser(["none","ascii","ascii2","sharp","rounded","reinforced","markdown","grid"]).help("Specify the border style"))
        .arg(Arg::new("padding").short('p').long("padding").default_value("1").value_name("PADDING").value_parser(value_parser!(usize)).help("Specify padding for table cell"))
        .arg(Arg::new("indent").short('i').long("indent").default_value("0").value_name("INDENT").value_parser(value_parser!(usize)).help("Specify global indent for table"))
        .arg(Arg::new("sniff").long("sniff").default_value("1000").value_name("LIMIT").value_parser(value_parser!(usize)).help("Limit column widths sniffing to the specified number of rows. Specify \"0\" to cancel limit"))
        .arg(Arg::new("header-align").long("header-align").default_value("center").value_name("HEADER_ALIGN").value_parser(["left","center","right"]).help("Specify the alignment of the table header"))
        .arg(Arg::new("body-align").long("body-align").default_value("left").value_name("BODY_ALIGN").value_parser(["left","center","right"]).help("Specify the alignment of the table body"))
        .arg(Arg::new("disable-pager").short('P').long("disable-pager").action(ArgAction::SetTrue).help("Disable pager"))
        .get_matches();

    let file_opt: Option<String> = cmd.get_one::<String>("FILE").cloned();
    let no_headers = cmd.get_flag("no-headers");
    let number = cmd.get_flag("number");
    let tsv = cmd.get_flag("tsv");
    let delimiter: char = if tsv { '\t' } else { *cmd.get_one::<char>("delimiter").unwrap() };
    let style_str = cmd.get_one::<String>("style").unwrap().clone();
    let style = match style_str.as_str() {
        "none" => Style::None,
        "ascii" => Style::Ascii,
        "ascii2" => Style::Ascii2,
        "sharp" => Style::Sharp,
        "rounded" => Style::Rounded,
        "reinforced" => Style::Reinforced,
        "markdown" => Style::Markdown,
        "grid" => Style::Grid,
        _ => Style::Sharp,
    };
    let padding = *cmd.get_one::<usize>("padding").unwrap();
    let indent = *cmd.get_one::<usize>("indent").unwrap();
    let sniff_limit = *cmd.get_one::<usize>("sniff").unwrap();
    let sniff = if sniff_limit == 0 { usize::MAX } else { sniff_limit };
    let header_align = match cmd.get_one::<String>("header-align").unwrap().as_str() {
        "left" => Align::Left,
        "center" => Align::Center,
        "right" => Align::Right,
        _ => Align::Center,
    };
    let body_align = match cmd.get_one::<String>("body-align").unwrap().as_str() {
        "left" => Align::Left,
        "center" => Align::Center,
        "right" => Align::Right,
        _ => Align::Left,
    };

    let input_string = if let Some(fp) = file_opt {
        match std::fs::read_to_string(&fp) {
            Ok(c) => c,
            Err(_) => { eprintln!("csview: No such file or directory (os error 2)"); std::process::exit(1); }
        }
    } else {
        let mut buf = String::new();
        let stdin = io::stdin();
        let mut h = stdin.lock();
        h.read_to_string(&mut buf).unwrap_or(0);
        buf
    };

    let records = match parse_csv(&input_string, delimiter) {
        Ok(r) => r,
        Err((rec_idx, line, byte, actual, expected)) => {
            eprintln!("csview: CSV error: record {} (line: {}, byte: {}): found record with {} fields, but the previous record has {} fields", rec_idx, line, byte, actual, expected);
            std::process::exit(1);
        }
    };

    let has_headers = !no_headers;
    let mut data_header: Option<Vec<String>> = None;
    let mut data_body: Vec<Vec<String>> = Vec::new();
    if has_headers {
        if records.is_empty() {
            data_header = Some(vec![]);
        } else {
            data_header = Some(records[0].clone());
            if records.len() > 1 { data_body = records[1..].to_vec(); }
        }
    } else {
        data_body = records.clone();
    }

    let mut final_header: Option<Vec<String>> = None;
    let mut final_body: Vec<Vec<String>> = Vec::new();
    let mut num_columns = 0;

    if number {
        if has_headers {
            let mut hdr = vec!["#".to_string()];
            if let Some(ref dh) = data_header { hdr.extend(dh.clone()); }
            final_header = Some(hdr);
            for (idx, row) in data_body.iter().enumerate() {
                let mut nr = vec![(idx+1).to_string()];
                nr.extend(row.clone());
                final_body.push(nr);
            }
            num_columns = final_header.as_ref().map(|h| h.len()).unwrap_or(1);
            if num_columns==0 { num_columns=1; }
        } else {
            for (idx, row) in data_body.iter().enumerate() {
                let mut nr = vec![(idx+1).to_string()];
                nr.extend(row.clone());
                final_body.push(nr);
            }
            if data_body.is_empty() { num_columns=1; } else { num_columns=final_body[0].len(); }
        }
    } else {
        final_header = data_header.clone();
        final_body = data_body.clone();
        if let Some(ref hdr) = final_header { num_columns=hdr.len(); }
        else if !final_body.is_empty() { num_columns=final_body[0].len(); }
        else { num_columns=0; }
    }

    let mut col_widths = vec![0; num_columns];
    if number && !col_widths.is_empty() { col_widths[0]=display_width("#"); }
    if let Some(ref hdr) = final_header {
        for (i, cell) in hdr.iter().enumerate() {
            if i<col_widths.len() {
                let w=display_width(cell);
                if w>col_widths[i] { col_widths[i]=w; }
            }
        }
    }
    let sniff_count = std::cmp::min(sniff, final_body.len());
    for row_idx in 0..sniff_count {
        for (i, cell) in final_body[row_idx].iter().enumerate() {
            if i<col_widths.len() {
                let w=display_width(cell);
                if w>col_widths[i] { col_widths[i]=w; }
            }
        }
    }

    let borders = get_borders(style);
    let indent_str = " ".repeat(indent);
    let mut out_lines = Vec::new();

    if let Some(hdr) = final_header {
        if let Some(top) = build_border_line(&borders, "top", &col_widths, padding) {
            out_lines.push(format!("{}{}", indent_str, top));
        }
        let mut aligned_cells = Vec::new();
        for (i, cell) in hdr.iter().enumerate() {
            let cw = col_widths.get(i).cloned().unwrap_or(0);
            let cw_cell = display_width(cell);
            let (trunc, trunc_w) = if cw_cell>cw { truncate_str(cell, cw) } else { (cell.clone(), cw_cell) };
            aligned_cells.push(align_string(&trunc, trunc_w, cw, header_align));
        }
        out_lines.push(format!("{}{}", indent_str, build_row_line(&borders, &aligned_cells, padding)));
        if !final_body.is_empty() {
            if let Some(mid) = build_border_line(&borders, "mid", &col_widths, padding) {
                out_lines.push(format!("{}{}", indent_str, mid));
            }
            for (b_idx, row) in final_body.iter().enumerate() {
                let mut aligned_cells = Vec::new();
                for (i, cell) in row.iter().enumerate() {
                    let cw = col_widths.get(i).cloned().unwrap_or(0);
                    let cw_cell = display_width(cell);
                    let (trunc, trunc_w) = if cw_cell>cw { truncate_str(cell, cw) } else { (cell.clone(), cw_cell) };
                    aligned_cells.push(align_string(&trunc, trunc_w, cw, body_align));
                }
                out_lines.push(format!("{}{}", indent_str, build_row_line(&borders, &aligned_cells, padding)));
                if style==Style::Grid && b_idx+1<final_body.len() {
                    if let Some(mid) = build_border_line(&borders, "mid", &col_widths, padding) {
                        out_lines.push(format!("{}{}", indent_str, mid));
                    }
                }
            }
        }
        if let Some(bot) = build_border_line(&borders, "bottom", &col_widths, padding) {
            out_lines.push(format!("{}{}", indent_str, bot));
        }
    } else {
        if final_body.is_empty() {
            if let Some(top) = build_border_line(&borders, "top", &col_widths, padding) {
                out_lines.push(format!("{}{}", indent_str, top));
            }
            if let Some(bot) = build_border_line(&borders, "bottom", &col_widths, padding) {
                out_lines.push(format!("{}{}", indent_str, bot));
            }
        } else {
            if let Some(top) = build_border_line(&borders, "top", &col_widths, padding) {
                out_lines.push(format!("{}{}", indent_str, top));
            }
            for (b_idx, row) in final_body.iter().enumerate() {
                let mut aligned_cells = Vec::new();
                for (i, cell) in row.iter().enumerate() {
                    let cw = col_widths.get(i).cloned().unwrap_or(0);
                    let cw_cell = display_width(cell);
                    let (trunc, trunc_w) = if cw_cell>cw { truncate_str(cell, cw) } else { (cell.clone(), cw_cell) };
                    aligned_cells.push(align_string(&trunc, trunc_w, cw, body_align));
                }
                out_lines.push(format!("{}{}", indent_str, build_row_line(&borders, &aligned_cells, padding)));
                if style==Style::Grid && b_idx+1<final_body.len() {
                    if let Some(mid) = build_border_line(&borders, "mid", &col_widths, padding) {
                        out_lines.push(format!("{}{}", indent_str, mid));
                    }
                }
            }
            if let Some(bot) = build_border_line(&borders, "bottom", &col_widths, padding) {
                out_lines.push(format!("{}{}", indent_str, bot));
            }
        }
    }

    for l in out_lines { println!("{}", l); }
}
