                        }
                    } else { expected_len = Some(actual); }
                    records.push(fields.clone());
                    fields.clear();
                    record_start_byte = next_byte_idx + 1;
                    line += 1;
                    record_start_line = line;
                    record_index += 1;
                    at_field_start = true;
                    in_quotes = false;
                }
                continue;
            } else {
                if in_quotes {
                    field.push('\n');
                    line += 1;
                } else {
                    if at_field_start && fields.is_empty() && field.is_empty() {
                        record_start_byte = byte_idx + ch.len_utf8();
                        line += 1;
                        record_start_line = line;
                        field.clear();
                        fields.clear();
                        at_field_start = true;
                        continue;
                    }
                    fields.push(field.clone());
                    field.clear();
                    let actual = fields.len();
                    if let Some(exp) = expected_len {
                        if actual != exp {
                            return Err((record_index, record_start_line, record_start_byte, actual, exp));
                        }
                    } else { expected_len = Some(actual); }
                    records.push(fields.clone());
                    fields.clear();
                    record_start_byte = byte_idx + ch.len_utf8();
                    line += 1;
                    record_start_line = line;
                    record_index += 1;
                    at_field_start = true;
                    in_quotes = false;
                }
                continue;
            }
        }
        if ch == '\n' {
            if in_quotes {
                field.push('\n');
                line += 1;
            } else {
                if at_field_start && fields.is_empty() && field.is_empty() {
                    record_start_byte = byte_idx + ch.len_utf8();
                    line += 1;
                    record_start_line = line;
                    field.clear();
                    fields.clear();
                    at_field_start = true;
                    continue;
                }
                fields.push(field.clone());
                field.clear();
                let actual = fields.len();
                if let Some(exp) = expected_len {
                    if actual != exp {
                        return Err((record_index, record_start_line, record_start_byte, actual, exp));
                    }
                } else { expected_len = Some(actual); }
                records.push(fields.clone());
                fields.clear();
                record_start_byte = byte_idx + ch.len_utf8();
                line += 1;
                record_start_line = line;
                record_index += 1;
                at_field_start = true;
                in_quotes = false;
            }
            continue;
        }
        if ch == delimiter && !in_quotes {
            fields.push(field.clone());
            field.clear();
            at_field_start = true;
            continue;
        }
        if ch == '"' {
            if at_field_start && !in_quotes {
                in_quotes = true;
                at_field_start = false;
                continue;
            } else if in_quotes {
                if let Some((_, '"')) = chars.peek() {
                    field.push('"');
                    chars.next();
                    at_field_start = false;
                } else {
                    in_quotes = false;
